import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable

@Composable
fun AppNav(navController: NavHostController) {
    NavHost(navController = navController, startDestination = "list") {
        composable("list") { Text("Список задач") }
        composable("detail/{id}") { entry ->
            val id = entry.arguments?.getString("id")
            Text("Задача $id")
        }
    }
}

fun main() {
    val nav = NavHostController()
    println(stubs.ComposeLog.render { AppNav(nav) })
    nav.navigate("detail/7")
    println(stubs.ComposeLog.render { AppNav(nav) })
}

fun detailRoute(id: Int) = "detail/$id"

composable(
    route = "detail/{id}",
    arguments = listOf(navArgument("id") { type = NavType.IntType })
) { entry ->
    val id = entry.arguments?.getInt("id")
    // по номеру достаём задачу из базы через ViewModel
}

class Screens {
    private val stack = mutableListOf("list")

    fun go(route: String) {
        stack.add(route)
    }

    fun back(): Boolean {
        if (stack.size == 1) return false
        stack.removeAt(stack.size - 1)
        return true
    }

    fun current(): String = stack.last()
}

fun main() {
    val s = Screens()
    s.go("detail/1")
    s.go("settings")
    println(s.current())
    s.back()
    println(s.current())
    s.back()
    println(s.back())
}

@Composable
fun ListScreen(onOpen: (Int) -> Unit) {
    Button(onClick = { onOpen(7) }) { Text("Открыть задачу 7") }
}

// в карте экранов:
composable("list") {
    ListScreen(onOpen = { id -> navController.navigate(detailRoute(id)) })
}

navController.navigate("main") {
    popUpTo("login") { inclusive = true }
    launchSingleTop = true
}
